// Story pacing: one defeated chapter is half a level; equipment is still per chapter.
export const CHAPTER_COUNT=18;
export const DEFEATS_PER_LEVEL=2;
export const levelFor=completed=>1+Math.floor(Math.max(0,Math.min(CHAPTER_COUNT,completed))/DEFEATS_PER_LEVEL);
export function earnedDefeats(state){return Math.min(CHAPTER_COUNT,Math.max(state.completed||0,state.defeated||0));}
export function experienceFor(state){
 const claimed=Math.floor((state.completed||0)/DEFEATS_PER_LEVEL)*DEFEATS_PER_LEVEL;
 return Math.max(0,Math.min(100,(earnedDefeats(state)-claimed)*50));
}
